            4'b0101: tseg = 8'b10110110; 
            4'b0110: tseg = 8'b10111110; 
            4'b0111: tseg = 8'b11100100; 
            4'b1000: tseg = 8'b11111110; 
            4'b1001: tseg = 8'b11110110; 
            default: tseg = 8'b00000000; 
        endcase

    end
    assign seg = tseg;
endmodule

